  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Family and Possessives$j$, $j${"readings": [{"title": "Ephesians 6 (King James Version)", "url": "/portal/bible/Ephesians/6"}], "body": "Ephesians 6:2 says, Honour thy father and mother; which is the first commandment with promise. In Spanish speaking cultures the family is at the center of life, and learning family words is one of the first steps to friendship.\n\nFamily words include la familia for family, el padre or papá for father, la madre or mamá for mother, los padres for parents, el hermano and la hermana for brother and sister, el hijo and la hija for son and daughter, el abuelo and la abuela for grandfather and grandmother, el tío and la tía for uncle and aunt, el primo and la prima for cousin, el esposo and la esposa for husband and wife, and el nieto and la nieta for grandson and granddaughter. When a word can mean both males and females together, Spanish uses the masculine plural, so los hermanos can mean brothers or brothers and sisters, and los padres means parents.\n\nPossessive adjectives show who owns something. Mi means my, tu means your, su means his, her, its, your formal or their, nuestro means our, and they agree in number with the thing owned. Mi hermano is my brother and mis hermanos is my brothers. Tu madre is your mother. Su familia can mean his family, her family or their family. To say of, Spanish uses de, as in la casa de mi abuela, which means my grandmother's house.\n\nUseful phrases include Tengo dos hermanos for I have two brothers, Mi familia es grande for my family is big and ¿Cuántas personas hay en tu familia? for how many people are in your family?\n\nYour task: (1) Write five sentences about your family in Spanish. (2) Translate my cousins and our grandmother.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Ephesians 6:2 says, Honour thy father and mother; which is the first commandment with promise. The family is at the center of Spanish speaking cultures.\n\nNow watch this. La madre, el padre, los padres. El hermano, la hermana. El hijo, la hija. El abuelo, la abuela. El tío, la tía. El primo, la prima. El esposo, la esposa.\n\nWhen a group has males and females, Spanish uses the masculine plural. Los hermanos can mean brothers and sisters.\n\nPossessives are mi, tu, su and nuestro. Mi hermano, mis hermanos. To say of, use de. La casa de mi abuela.\n\nYour task is to write five sentences about your family and translate two phrases. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Family and Possessives$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Nouns, Articles, Gender and Number$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "In the beginning, God created order, and Spanish grammar also has a pattern. Genesis 1:27 says, So God created man in his own image, in the image of God created he him; male and female created he them. Spanish nouns also have gender. Every noun is either masculine or feminine, even for things.\n\nMost nouns that end in o are masculine, such as el libro, and most that end in a are feminine, such as la mesa. Nouns that end in ción, sión, dad and tad are feminine, such as la canción and la libertad. Common exceptions are el día, el mapa, el problema, el programa, la mano and la foto. Nouns that end in e or a consonant must be learned one at a time, such as el nombre and la clase.\n\nThe definite articles mean the. El is masculine singular, la is feminine singular, los is masculine plural and las is feminine plural. The indefinite articles mean a, an or some. Un is masculine singular, una is feminine singular, unos is masculine plural and unas is feminine plural. El libro, los libros, una casa, unas casas.\n\nTo make a noun plural, add s if it ends in a vowel, as in libro to libros. Add es if it ends in a consonant, as in lección to lecciones. If a noun ends in z, change z to c and add es, as in lápiz to lápices. Articles must match the noun in gender and number.\n\nYour task: (1) Add the correct definite article to casa, libro, canción, día and mano. (2) Make these plural: el amigo, la lección, el lápiz.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Genesis 1:27 says God created male and female. Spanish nouns also have gender. Every noun is masculine or feminine.\n\nNow watch this. Most nouns ending in o are masculine, like el libro. Most ending in a are feminine, like la mesa. Nouns ending in ción, sión, dad and tad are feminine. Watch the exceptions. El día, el mapa, el problema, la mano.\n\nThe definite articles are el, la, los and las. The indefinite articles are un, una, unos and unas.\n\nFor plurals, add s after a vowel and es after a consonant. Change z to c in lápiz and say lápices. The article must match the noun.\n\nYour task is to add articles and make plurals. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Nouns, Articles, Gender and Number$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Adjectives and Describing People$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made. Describing people with kind and honest words is a way to honor what God has made.\n\nIn Spanish, adjectives usually come after the noun and must agree with it in gender and number. If the noun is feminine, the adjective changes to match. Adjectives that end in o have four forms: alto, alta, altos, altas. Adjectives that end in e or a consonant have the same form for masculine and feminine, such as inteligente, fácil and joven, and add s or es for plural. Examples include el chico alto, la chica alta, los chicos altos, las chicas altas, la madre inteligente and los abuelos inteligentes.\n\nUseful adjectives include alto for tall, bajo for short, grande for big, pequeño for small, joven for young, viejo for old, bonito for pretty, feo for ugly, simpático for nice, antipático for unpleasant, trabajador for hardworking, divertido for fun, serio for serious, amable for kind, generoso for generous and callado for quiet. Bueno and malo shorten before a masculine singular noun, so we say un buen amigo and un mal día. Grande shortens to gran before a singular noun and means great, as in un gran hombre. Colors are adjectives too, such as rojo, azul, verde, negro and blanco.\n\nSpanish speakers often use adjectives with ser, as in Mi madre es amable. Always describe people with respect and kindness.\n\nYour task: (1) Describe a family member using four adjectives with correct agreement. (2) Translate the tall girls and the kind grandfather.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Psalm 139:14 says, I am fearfully and wonderfully made. Describing people kindly honors what God has made.\n\nNow watch this. In Spanish, the adjective usually comes after the noun and agrees in gender and number. El chico alto. La chica alta. Los chicos altos. Las chicas altas.\n\nAdjectives ending in e or a consonant do not change for gender. Inteligente, fácil, joven. Just add s or es for plural.\n\nUseful adjectives are alto, bajo, grande, pequeño, joven, viejo, simpático, trabajador, divertido, amable and generoso. Bueno shortens to buen before a masculine noun, like un buen amigo.\n\nYour task is to describe a family member with four adjectives and translate two phrases. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Adjectives and Describing People$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 The Verbs Ser, Estar and Tener$j$, $j${"readings": [{"title": "Psalm 100 (King James Version)", "url": "/portal/bible/Psalms/100"}], "body": "Psalm 100:3 says, Know ye that the LORD he is God: it is he that hath made us, and not we ourselves. Spanish has two verbs that mean to be, ser and estar, and they are not interchangeable. Learning the difference is one of the keys to speaking well.\n\nUse ser for identity, origin, nationality, occupation, characteristics, time, dates and possession. Yo soy estudiante. Ella es de Cuba. Son las tres. Use estar for location, temporary conditions and feelings. Estoy en la iglesia. Mi madre está cansada. Estamos felices. Ser forms: soy, eres, es, somos, son. Estar forms: estoy, estás, está, estamos, están. Compare Él es aburrido, which means he is boring, and Él está aburrido, which means he is bored.\n\nThe verb tener means to have. Its forms are tengo, tienes, tiene, tenemos and tienen. Tener is also used in expressions that use to be in English. Tengo hambre means I am hungry, tengo sed means I am thirsty, tengo frío means I am cold, tengo calor means I am hot, tengo sueño means I am sleepy and tengo miedo means I am afraid. Age also uses tener, as in Tengo quince años. Tener que plus a verb means to have to, as in Tengo que estudiar.\n\nTo check yourself, remember the phrase DOCTOR for ser: description, occupation, characteristic, time, origin, relationship. And remember PLACE for estar: position, location, action, condition, emotion.\n\nYour task: (1) Write three sentences with ser and three with estar. (2) Write three tener expressions.\n\nFlorida standards: WL.912.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "WL.912", "script": "Welcome back. Listen, Psalm 100:3 says, it is he that hath made us, and not we ourselves.\n\nNow watch this. Spanish has two verbs for to be. Use ser for identity, origin, occupation, characteristics, time and dates. Use estar for location, temporary conditions and feelings. Ser is soy, eres, es, somos, son. Estar is estoy, estás, está, estamos, están.\n\nEstoy en la iglesia. Mi madre está cansada. Ella es de Cuba.\n\nTener means to have. Tengo, tienes, tiene, tenemos, tienen. Spanish uses tener for hunger, thirst, cold, heat, sleepiness, fear and age. Tengo hambre. Tengo quince años. Tengo que estudiar means I have to study.\n\nYour task is to write three sentences with ser, three with estar and three with tener. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 The Verbs Ser, Estar and Tener$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Family, Nouns, Adjectives and the Verbs Ser, Estar and Tener$j$, $j${"prompt": "Write a report of at least 250 words in English with Spanish examples. Use complete sentences and label each part. Ephesians 6:2 says, Honour thy father and mother; which is the first commandment with promise.\n\nPart 1: List ten family words in Spanish with meanings and explain how possessive adjectives agree with the noun.\nPart 2: Explain how to tell whether a noun is masculine or feminine, list the four definite articles and the four indefinite articles, and show how to make nouns plural.\nPart 3: Write a paragraph in Spanish of at least six sentences describing your family or a friend, using adjectives that agree with the nouns.\nPart 4: Explain when to use ser and when to use estar, and give three examples of each. Write five tener expressions.\nPart 5: Explain how Ephesians 6:2 and Psalm 139:14 guide the way you speak about family and describe others.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Family, Nouns, Adjectives and the Verbs Ser, Estar and Tener$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Honour Thy Father and Mother$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a family member or mentor who has taught you something important, (2) uses at least five Spanish words or phrases from this unit, (3) explains why gender and agreement matter when you want to speak clearly and respectfully, and (4) connects your answer to Ephesians 6:2, Psalm 139:14 or Psalm 100:3. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do you think languages have patterns like gender and agreement? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Honour Thy Father and Mother$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Family and Possessives$j$, $j${"questions": [{"q": "La abuela is:", "options": ["The sister", "The aunt", "The grandmother", "The mother"]}, {"q": "Los padres can mean:", "options": ["Cousins", "Brothers", "Priests only", "Parents"]}, {"q": "My brothers in Spanish is:", "options": ["Mi hermanos", "Mis hermano", "Mis hermanos", "Tu hermanos"]}, {"q": "La casa de mi abuela means:", "options": ["My mother's school", "Our grandfather's house", "My grandmother's house", "The house of my aunt"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Family and Possessives$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,2,2}'::int[], array[$j$Abuela means grandmother.$j$,$j$Padres means parents.$j$,$j$The possessive agrees in number with the noun.$j$,$j$De shows ownership.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Family and Possessives$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Nouns, Articles, Gender and Number$j$, $j${"questions": [{"q": "The article for mesa is:", "options": ["El", "Los", "La", "Un"]}, {"q": "Which word is masculine?", "options": ["Mesa", "Día", "Canción", "Libertad"]}, {"q": "The plural of lección is:", "options": ["Leccións", "Lecciones", "Leccion", "Lecciónes"]}, {"q": "The plural of lápiz is:", "options": ["Lápiz", "Lápizs", "Lápizes", "Lápices"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Nouns, Articles, Gender and Number$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,3}'::int[], array[$j$Mesa is feminine singular.$j$,$j$Día is a common masculine exception.$j$,$j$Add es after a consonant and drop the accent.$j$,$j$Change z to c and add es.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Nouns, Articles, Gender and Number$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Adjectives and Describing People$j$, $j${"questions": [{"q": "How do you say The girl is tall in Spanish?", "options": ["La chica es alta", "El chica es alta", "La chica es alto", "La chica es altos"]}, {"q": "Which adjective stays the same for masculine and feminine?", "options": ["Alto", "Inteligente", "Bajo", "Callado"]}, {"q": "Un buen amigo means:", "options": ["A bad friend", "A good friend", "A tall friend", "A big friend"]}, {"q": "In Spanish, adjectives usually go:", "options": ["Before the noun", "At the end of the sentence only", "After the noun", "Nowhere"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Adjectives and Describing People$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,2}'::int[], array[$j$Alta is the feminine singular form.$j$,$j$Adjectives ending in e do not change for gender.$j$,$j$Bueno shortens to buen before a masculine singular noun.$j$,$j$Descriptive adjectives follow the noun.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Adjectives and Describing People$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: The Verbs Ser, Estar and Tener$j$, $j${"questions": [{"q": "Which verb tells location?", "options": ["Estar", "Hacer", "Ser", "Tener"]}, {"q": "Ella ___ de Cuba.", "options": ["son", "es", "tiene", "está"]}, {"q": "Tengo hambre means:", "options": ["I have a hand", "I am thirsty", "I am tall", "I am hungry"]}, {"q": "Nosotros ___ en la iglesia.", "options": ["estamos", "tenemos", "están", "somos"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Verbs Ser, Estar and Tener$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$Estar is used for where something is.$j$,$j$Origin uses ser.$j$,$j$Hambre means hunger.$j$,$j$Location uses estar and nosotros takes estamos.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Verbs Ser, Estar and Tener$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Family, Nouns, Adjectives and the Verbs Ser, Estar and Tener$j$, $j${"questions": [{"q": "El hermano means:", "options": ["The brother", "The grandson", "The uncle", "The father"]}, {"q": "Su familia can mean:", "options": ["Your friends", "Only my family", "Only our family", "His, her or their family"]}, {"q": "The plural of el amigo is:", "options": ["El amigos", "Los amigo", "Los amigos", "Las amigos"]}, {"q": "Which article goes with problema?", "options": ["El", "Una", "Las", "La"]}, {"q": "Las chicas simpáticas means:", "options": ["The nice boy", "The tall girls", "The nice girls", "A nice girl"]}, {"q": "Mi madre ___ cansada.", "options": ["tiene", "son", "está", "es"]}, {"q": "Tienen means:", "options": ["We have", "I have", "You have", "They have"]}, {"q": "Tengo que estudiar means:", "options": ["I will study", "I like to study", "I am studying", "I have to study"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Family, Nouns, Adjectives and the Verbs Ser, Estar and Tener$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,0,2,2,3,3}'::int[], array[$j$Hermano is brother.$j$,$j$Su has several meanings.$j$,$j$Article and noun both become plural.$j$,$j$Problema is a masculine exception.$j$,$j$Simpáticas is feminine plural.$j$,$j$A temporary condition uses estar.$j$,$j$Tienen is the ellos form of tener.$j$,$j$Tener que means to have to.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Family, Nouns, Adjectives and the Verbs Ser, Estar and Tener$j$ on conflict (item_id) do nothing;
